{# 
Last updated by Diego 28/04/2026 for NYPR>
Previously Updated 31/10/2023 for 1.3.0 
-  Previously updated November 2021: trim output of data.description, add Rights Statement mapping, and show trimmed output for data.rights (local rights statement) #} 
{#- ------ Macros Start ----- -#}
{# modified from general use to render like the results #}
{%- macro html_output(html_title, source_datum, list_wrapper, markdown, rich) -%}
  {# Handle Drupal-style objects with a "value" property #}
  {% set list_wrapper = list_wrapper|default("p") %}
  {% set markdown = markdown|default(false) %}
  {% set rich = rich|default(false) %}

  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}
 
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
     <div class="row">
    {%- if html_title|length > 0 -%}
     <div class="col-3">
     <h5>{{ html_title }}</h5>
     </div>
    {%- endif -%}
    <div class="col-9 fw-light">
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown and source_data is instanceof('scalar') -%}
          {{ source_data|markdown_2_html }}
        {%- else -%}
          {%- if rich and source_data is instanceof('scalar')-%}
            <{{ list_wrapper }}>{{ source_data|raw }}</{{ list_wrapper }}>
          {%- elseif source_data is instanceof('scalar') -%}
            <{{ list_wrapper }}>{{ source_data|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        {{ source_datum|markdown_2_html }}
      {%- else -%}
        {%- if rich -%}
          {%- if list_wrapper|length > 0 -%}
            <{{ list_wrapper }}>{{ source_datum|raw }}</{{ list_wrapper }}>
          {%- else -%}
            {{ source_datum|raw }}
          {%- endif -%}
          {%- else -%}
          <{{ list_wrapper }}>{{ source_datum|striptags }}</{{ list_wrapper }}>
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
    </div>
    </div>
  {%- endif -%}
   
{%- endmacro html_output -%}

<blockquote class="blockquote"> 
{% set possible_predicates = ["ismemberof","ispartof","ismemberofseries"] %}
{% set accumulated_links = [] %}
{% for predicate in possible_predicates %}
  {% if attribute(data, predicate)  %} 
    {% if attribute(data, predicate) is iterable %} 
	  {% for parent_id in attribute(data, predicate)%} 
        {% if parent_id is instanceof("numeric") %}
		  {% set parentnode = bamboo_load_entity('node', parent_id) %} 
          {% if parentnode %}
            {% set parentnode_type = parentnode.field_descriptive_metadata.0.value|sbf_json_decode %}
            {% set parentnode_type = "" ~ (parentnode_type['type'] is iterable ? parentnode_type['type'][0] ~ ': ' : parentnode_type['type']  ~ ': ') %}
		    {% set parentnodeurl = url('entity.node.canonical', {'node': parentnode.id}, {'absolute': true}) %} 
			  {# first check if we have a parent type first #}
              {% set link = '<div class="blockquote-footer">In ' ~ parentnode_type ~ '<cite title="'  ~ parentnode.title.value ~ '"><a href="' ~ parentnodeurl|render ~ '">' ~ parentnode.title.value ~ '</a></cite></div>' %}
              {% if link not in accumulated_links %}
                {% set accumulated_links = accumulated_links|merge([link]) %}
              {% endif %}
           {% endif %}
        {% endif %}   
	  {% endfor %} 
    {% else %} 
      {% if attribute(data, predicate) is instanceof("numeric") %}
	    {% set parentnode = bamboo_load_entity('node', attribute(data, predicate)) %} 
        {% if parentnode %} 
          {% set parentnode_type = parentnode.field_descriptive_metadata.0.value|sbf_json_decode %}
          {% set parentnode_type = "" ~ (parentnode_type['type'] is iterable ? parentnode_type['type'][0]  ~ ': ' : parentnode_type['type']  ~ ': ') %}
		  {% set parentnodeurl = url('entity.node.canonical', {'node': attribute(data, predicate)}, {'absolute': true}) %}
           {% set link = '<div class="blockquote-footer">In ' ~ parentnode_type ~ '<cite title="'  ~ parentnode.title.value ~ '"><a href="' ~ parentnodeurl|render ~ '">' ~ parentnode.title.value ~ '</a></cite></div>'  %}
           {% if link not in accumulated_links %}
               {% set accumulated_links = accumulated_links|merge([link]) %}
            {% endif %}
        {% endif %} 
      {% endif %} 
    {% endif %}
  {% endif %}
{% endfor %}
{% if accumulated_links is iterable and not empty %}
  {% for links in accumulated_links %}
  {{ _self.html_output('', links,  list_wrapper = "div", markdown = false, rich = true) }}
  {% endfor %}
{% endif %}
</blockquote> 
{{ _self.html_output('Type', data.type, 'p') }} 
{{ _self.html_output('Rights', data.rights, 'p') }}
{% if data.dates_edtf|length > 0 %}
 {% set dates_humanized = [] %}
 {% for dates in data.dates_edtf %}
    {% set dates_humanized = dates_humanized|merge(['<span class="fw-bold">' ~ dates.date_type|capitalize ~ '</span> : ' ~  dates.date|trim|edtf_2_human_date('en')]) %}
  {% endfor %}
  {{ _self.html_output("Dates", dates_humanized,  list_wrapper = "p", markdown = false, rich = true) }}
{% endif %}
{{ _self.html_output('Medium', data.medium, 'p') }}
